import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing, delayRender, continueRender, cancelRender } from '../remotionShim';
// ---------------------------------------------------------------------------
// BRAND FONT LOADING (Module Level)
// ---------------------------------------------------------------------------
if (typeof document !== "undefined") {
  const loadCustomFont = (family: string, url: string) => {
    const handle = delayRender(`Loading ${family}`);
    const font = new FontFace(family, `url('${url}') format('truetype')`);
    font.load()
      .then(() => {
        document.fonts.add(font);
        continueRender(handle);
      })
      .catch((err) => {
        console.log(`Error loading ${family}`, err);
        cancelRender(err);
      });
  };
  loadCustomFont("TuskerGrotesk", "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/brand_guidelines/fonts/4b954368156447d584b4e82c28890f47.ttf");
}

// ---------------------------------------------------------------------------
// SCHEMA
// ---------------------------------------------------------------------------


export type MacromoneyTitleProps = Record<string, any>;

// ---------------------------------------------------------------------------
// HELPER FUNCTIONS FOR GENERATIVE GRAPHICS
// ---------------------------------------------------------------------------
const generateJaggedLine = (startX: number, startY: number, segments: number, xStep: number, yRange: number, seed: number) => {
  let d = `M ${startX} ${startY}`;
  let curX = startX;
  let curY = startY;
  for (let i = 1; i <= segments; i++) {
    curX += xStep;
    const offset = Math.sin(seed * i * 12.345) * yRange;
    curY += offset;
    d += ` L ${curX} ${curY}`;
  }
  return d;
};

// ---------------------------------------------------------------------------
// MAIN COMPONENT
// ---------------------------------------------------------------------------
const MacromoneyTitle: React.FC<MacromoneyTitleProps> = ({
  title = "MACRO",
  titleFontFamily = "TuskerGrotesk",
  backgroundColor = "#1D191B",
  transparentBackground = false,
  dropletLandingYOffset = -63,
  dropletHoverGap = 108,
  durationInSeconds = 6,
}) => {
  const frame = useCurrentFrame();
  const { width, height, fps, durationInFrames } = useVideoConfig();
  const grainId = React.useId().replace(/:/g, "");

  const sf = durationInFrames / 180;
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Colors
  const cIvory = "#F2E9D8";
  const cRed = "#E21F26";
  const cChartreuse = "#C1D92B";
  const cGray = "#555555";
  const cLightGray = "#888888";

  // Font Stack
  const titleFontStack = `${titleFontFamily}, "Arial Narrow", sans-serif`;

  // ---------------------------------------------------------------------------
  // CAMERA ANIMATION LOGIC
  // ---------------------------------------------------------------------------
  const focusStartX = width * 0.365;
  const focusStartY = height * 0.370;
  
  const driftPx = interpolate(frame, [0, 24 * sf], [focusStartX, focusStartX - 10], { extrapolateRight: "clamp" });
  const driftPy = interpolate(frame, [0, 24 * sf], [focusStartY, focusStartY + 5], { extrapolateRight: "clamp" });

  const pullProgress = interpolate(frame, [24 * sf, 138 * sf], [0, 1], {
    easing: Easing.bezier(0.6, 0.05, 0.4, 1),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp"
  });

  const curScale = Math.exp(interpolate(pullProgress, [0, 1], [Math.log(20), 0]));
  const curPx = interpolate(pullProgress, [0, 1], [driftPx, width / 2]);
  const curPy = interpolate(pullProgress, [0, 1], [driftPy, height / 2]);

  const vw = width / curScale;
  const vh = height / curScale;
  const vx = curPx - vw / 2;
  const vy = curPy - vh / 2;

  // ---------------------------------------------------------------------------
  // LIVE PATH TRUNCATION
  // ---------------------------------------------------------------------------
  const p0 = { x: 300, y: 700 };
  const p1 = { x: 500, y: 1000 };
  const p2 = { x: 900, y: 800 };
  
  const growT = interpolate(frame, [0, durationInFrames], [0.2, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  
  const L = (a: number, b: number, t: number) => a + (b - a) * t;
  const q0x = L(p0.x, p1.x, growT);
  const q0y = L(p0.y, p1.y, growT);
  const q1x = L(p1.x, p2.x, growT);
  const q1y = L(p1.y, p2.y, growT);
  const tipX = L(q0x, q1x, growT);
  const tipY = L(q0y, q1y, growT);
  
  const livePathD = `M ${p0.x} ${p0.y} Q ${q0x} ${q0y}, ${tipX} ${tipY}`;

  // ---------------------------------------------------------------------------
  // STATIC BACKGROUND GENERATION
  // ---------------------------------------------------------------------------
  const gridLines = useMemo(() => {
    const lines = [];
    for (let i = 0; i <= height; i += 60) {
      lines.push(<line key={`h-${i}`} x1={0} x2={width} y1={i} y2={i} stroke={cGray} strokeWidth={0.5} opacity={0.2} />);
    }
    for (let i = 0; i <= width; i += 60) {
      lines.push(<line key={`v-${i}`} x1={i} x2={i} y1={0} y2={height} stroke={cGray} strokeWidth={0.5} opacity={0.2} />);
    }
    return lines;
  }, [width, height, cGray]);

  const jaggedLines = useMemo(() => {
    return (
      <g>
        <path d={generateJaggedLine(0, 500, 40, 50, 40, 1)} fill="none" stroke={cLightGray} strokeWidth={1} opacity={0.4} />
        <path d={generateJaggedLine(200, 900, 30, 60, 60, 2)} fill="none" stroke={cIvory} strokeWidth={0.5} opacity={0.3} />
        <path d={generateJaggedLine(1000, 200, 20, 45, 20, 3)} fill="none" stroke={cRed} strokeWidth={1} opacity={0.5} />
      </g>
    );
  }, [cLightGray, cIvory, cRed]);

  // ---------------------------------------------------------------------------
  // PLAYFUL / PREMIUM TITLE SEQUENCE CHOREOGRAPHY
  // ---------------------------------------------------------------------------
  const s = Math.min(width, height) / 1080;
  const dropperSizeMultiplier = 1.75;
  const titleFontSize = 160 * s;
  const dripLandingY = titleFontSize * 0.62 + dropletLandingYOffset * s;  // tune to sit on the cap height of DOSE

  const macroOpacity = interpolate(frame, [125 * sf, 140 * sf], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const macroBlur = interpolate(frame, [125 * sf, 140 * sf], [10, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  // Consistent geometry calculation for dropper and droplet
  const dropperH = 140 * s * dropperSizeMultiplier;
  const dropletH = 18 * s * dropperSizeMultiplier;
  const TIP_RATIO = 135 / 140; // pipette tip within the viewBox

  const DROPPER_HOVER_GAP = dropletHoverGap * s;
  const dropperRestY = dripLandingY - DROPPER_HOVER_GAP - TIP_RATIO * dropperH;

  const dropperY = interpolate(
    frame,
    [130 * sf, 142 * sf, 155 * sf, 167 * sf],
    [-1100 * s, dropperRestY, dropperRestY, -1100 * s],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const dropperOpacity = interpolate(
    frame,
    [128 * sf, 132 * sf, 165 * sf, 169 * sf],
    [0, 1, 1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const dropperScaleY = interpolate(
    frame,
    [142 * sf, 145 * sf, 148 * sf],
    [1, 0.9, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const dropperScaleX = interpolate(
    frame,
    [142 * sf, 145 * sf, 148 * sf],
    [1, 1.05, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const liquidTop = interpolate(
    frame,
    [142 * sf, 145 * sf],
    [80, 134],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const showDroplet = frame >= 145 * sf && frame <= 153 * sf;

  const dropletScale = interpolate(
    frame,
    [145 * sf, 153 * sf],
    [0.7, 1.1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const pipetteTipY = dropperRestY + TIP_RATIO * dropperH;
  const startDropletY = pipetteTipY - dropletH; // droplet bottom at the pipette tip
  const endDropletY = dripLandingY - dropletH; // droplet bottom at the ripple center

  const dropletY = interpolate(
    frame,
    [145 * sf, 153 * sf],
    [startDropletY, endDropletY],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const dropletOpacity = interpolate(
    frame,
    [145 * sf, 146 * sf, 152 * sf, 153 * sf],
    [0, 1, 1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const showRipple = frame >= 153 * sf && frame <= 168 * sf;
  const rippleProgress = interpolate(
    frame,
    [153 * sf, 168 * sf],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const rippleScale = interpolate(rippleProgress, [0, 1], [0.1, 1.4]);
  const rippleOpacity = interpolate(rippleProgress, [0, 0.1, 0.6, 1], [0, 1, 0.4, 0]);

  const doseProgress = interpolate(
    frame,
    [153 * sf, 165 * sf],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const doseScale = interpolate(
    Easing.bezier(0.16, 1, 0.3, 1)(doseProgress),
    [0, 1],
    [0.5, 1]
  );
  const doseOpacity = interpolate(doseProgress, [0, 0.1, 1], [0, 1, 1]);
  const doseBlur = interpolate(doseProgress, [0, 1], [10, 0]);

  const mainTitle = title === "MACROMONEY" ? "MACRO" : title;
  const secondTitle = "DOSE";

  // Temporary diagnostic log to confirm the fix
  console.log(`Diagnostic: durationInFrames=${durationInFrames}, durationInSeconds * fps=${durationInSeconds * fps}`);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden", fontFamily: titleFontStack }}>
      
      {/* MACRO SYSTEM VISUALIZATION (CAMERA DRIVEN THROUGH VIEWBOX) */}
      <svg
        viewBox={`${vx} ${vy} ${vw} ${vh}`}
        width="100%"
        height="100%"
        style={{ position: "absolute", overflow: "visible" }}
      >
        <defs>
          <filter id="glow">
            <feGaussianBlur stdDeviation="2" />
          </filter>
        </defs>
        
        {/* Base Grid */}
        {gridLines}

        {/* Major Sweeping Curves */}
        <path d="M -100 900 C 300 900, 500 400, 700 400 S 1100 200, 2000 300" fill="none" stroke={cRed} strokeWidth={2} strokeLinecap="round" opacity={0.8} />
        <path d="M 200 100 Q 450 250, 700 400 T 1700 900" fill="none" stroke={cChartreuse} strokeWidth={1.5} strokeLinecap="round" opacity={0.7} />
        <path d="M 0 600 Q 350 500, 700 400 T 2000 100" fill="none" stroke={cIvory} strokeWidth={1} strokeLinecap="round" strokeDasharray="4 6" opacity={0.6} />

        {/* Jagged Trend Lines */}
        {jaggedLines}

        {/* Focal Node Nexus */}
        <g>
          <line x1={680} x2={720} y1={400} y2={400} stroke={cIvory} strokeWidth={1} />
          <line x1={700} x2={700} y1={380} y2={420} stroke={cIvory} strokeWidth={1} />
          <circle cx={700} cy={400} r={3} fill={cRed} />
          <circle cx={700} cy={400} r={8} fill="none" stroke={cRed} strokeWidth={0.5} opacity={0.5} />
          <text x={708} y={395} fill={cIvory} fontSize={8} letterSpacing={0.5}>0.382</text>
          <circle cx={690} cy={390} r={1} fill={cChartreuse} />
          <circle cx={715} cy={410} r={1} fill={cIvory} />
        </g>

        {/* Live Updating Projection Curve */}
        <g>
          <path d={livePathD} fill="none" stroke={cIvory} strokeWidth={1.5} strokeLinecap="round" opacity={0.8} />
          <circle cx={tipX} cy={tipY} r={2.5} fill={cIvory} />
          <circle cx={tipX} cy={tipY} r={8} fill={cIvory} opacity={0.2} filter="url(#glow)" />
          <text x={tipX + 8} y={tipY - 5} fill={cIvory} fontSize={6} letterSpacing={0.5} opacity={0.8}>PROJ</text>
        </g>

        {/* Secondary Details & Labels */}
        <g fontSize={10} fill={cLightGray} letterSpacing={1}>
          <text x={1500} y={150}>REAL GDP GROWTH</text>
          <line x1={1500} x2={1650} y1={155} y2={155} stroke={cGray} strokeWidth={0.5} />
          <text x={150} y={600} fill={cRed}>TERM PREMIUM</text>
          <circle cx={135} cy={597} r={2} fill={cRed} />
          <text x={1600} y={650}>YIELD CURVE</text>
          <path d="M 1600 660 Q 1700 700, 1800 680" fill="none" stroke={cGray} strokeWidth={1} />
          <text x={900} y={850} fill={cChartreuse}>VOLATILITY REGIME</text>
          <path d="M 850 870 Q 950 820, 1050 870 T 1250 870" fill="none" stroke={cChartreuse} strokeWidth={1} opacity={0.5} />
          <text x={350} y={750}>INFLATION EXPECTATIONS</text>
          <line x1={350} x2={550} y1={755} y2={755} stroke={cGray} strokeWidth={0.5} />
        </g>

        {/* Bottom Data Ticker / Axis */}
        <g transform={`translate(0, ${height - 40})`} fontSize={10} letterSpacing={1}>
          <line x1={50} x2={width - 50} y1={0} y2={0} stroke={cGray} strokeWidth={0.5} opacity={0.5} />
          <text x={100} y={20} fill={cLightGray}>EQUITIES</text>
          <text x={100} y={35} fill={cChartreuse}>+0.27%</text>
          <text x={350} y={20} fill={cLightGray}>RATES</text>
          <text x={350} y={35} fill={cRed}>-0.11%</text>
          <text x={600} y={20} fill={cLightGray}>CREDIT</text>
          <text x={600} y={35} fill={cChartreuse}>+0.08%</text>
          <text x={850} y={20} fill={cLightGray}>COMMODITIES</text>
          <text x={850} y={35} fill={cChartreuse}>+0.19%</text>
          <text x={1100} y={20} fill={cLightGray}>FX</text>
          <text x={1100} y={35} fill={cRed}>-0.04%</text>
          <text x={1350} y={20} fill={cLightGray}>GROWTH</text>
          <text x={1350} y={35} fill={cChartreuse}>+0.16%</text>
        </g>
      </svg>

      {/* HERO TITLE (Resolves in negative space after pullback) */}
      <AbsoluteFill
        style={{
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          zIndex: 10,
          pointerEvents: "none"
        }}
      >
        <div
          style={{
            fontSize: `${titleFontSize}px`,
            fontFamily: titleFontStack,
            color: cIvory,
            letterSpacing: "0.08em",
            textShadow: "0px 4px 12px rgba(0,0,0,0.6), 0px 0px 2px rgba(242, 233, 216, 0.2)",
            textAlign: "center",
            lineHeight: 1,
            display: "flex",
            flexDirection: "row",
            alignItems: "center",
            justifyContent: "center",
            transform: "translateX(0.04em)"
          }}
        >
          {/* MACRO */}
          <div
            style={{
              opacity: macroOpacity,
              filter: `blur(${macroBlur}px)`,
              color: cIvory,
              whiteSpace: "nowrap",
              transition: "none",
              height: `${titleFontSize}px`,
              display: "flex",
              alignItems: "center"
            }}
          >
            {mainTitle}
          </div>

          {/* Spacer */}
          <div style={{ width: "0.35em" }} />

          {/* DOSE Wrapper (Fixed height enforces identical boundary layout across headless systems) */}
          <div style={{ position: "relative", height: `${titleFontSize}px`, display: "flex", alignItems: "center" }}>
            <div
              style={{
                opacity: doseOpacity,
                filter: `blur(${doseBlur}px)`,
                transform: `scale(${doseScale})`,
                transformOrigin: "center center",
                color: cIvory,
                whiteSpace: "nowrap",
                transition: "none",
              }}
            >
              {secondTitle}
            </div>

            {/* Eyedropper & Droplet Overlay (Positioned dynamically above 'DOSE') */}
            <div
              style={{
                position: "absolute",
                inset: 0,
                pointerEvents: "none",
                overflow: "visible"
              }}
            >
              {/* Eyedropper Pipette */}
              <div
                style={{
                  position: "absolute",
                  top: dropperY,
                  left: "50%",
                  transform: `translateX(-50%) scale(${dropperScaleX}, ${dropperScaleY})`,
                  transformOrigin: "bottom center",
                  opacity: dropperOpacity,
                  transition: "none",
                }}
              >
                <svg width={40 * s * dropperSizeMultiplier} height={dropperH} viewBox="0 0 40 140" fill="none">
                  {/* Silicone Bulb */}
                  <path d="M 12 45 L 12 25 C 12 10, 28 10, 28 25 L 28 45 Z" fill={cRed} />
                  {/* Safety Flange Collar */}
                  <rect x={10} y={45} width={20} height={6} rx={1} fill={cIvory} />
                  {/* Glass Pipette Column */}
                  <path d="M 13 51 L 13 115 L 18 135 L 22 135 L 27 115 L 27 51 Z" fill="rgba(242, 233, 216, 0.15)" stroke={cIvory} strokeWidth={1.5} />
                  {/* Inside Concentrated Liquid */}
                  <path d={`M 14.5 ${liquidTop} L 14.5 115 L 18 133 L 22 133 L 25.5 115 L 25.5 ${liquidTop} Z`} fill={cRed} />
                </svg>
              </div>

              {/* Falling Droplet */}
              {showDroplet && (
                <div
                  style={{
                    position: "absolute",
                    top: dropletY,
                    left: "50%",
                    transform: `translateX(-50%) scale(${dropletScale})`,
                    transformOrigin: "bottom center",
                    opacity: dropletOpacity,
                    transition: "none",
                  }}
                >
                  <svg width={12 * s * dropperSizeMultiplier} height={dropletH} viewBox="0 0 12 18" fill="none">
                    <path d="M 6 0 C 6 0, 12 9, 12 13 C 12 16, 9.3 18, 6 18 C 2.7 18, 0 16, 0 13 C 0 9, 6 0, 6 0 Z" fill={cRed} />
                  </svg>
                </div>
              )}

              {/* Minimalist Micro Ripple Ring */}
              {showRipple && (
                <div
                  style={{
                    position: "absolute",
                    top: dripLandingY,
                    left: "50%",
                    transform: `translate(-50%, -50%) scale(${rippleScale})`,
                    width: 150 * s * dropperSizeMultiplier,
                    height: 150 * s * dropperSizeMultiplier,
                    border: `1.5px solid ${cRed}`,
                    borderRadius: "50%",
                    opacity: rippleOpacity,
                    pointerEvents: "none",
                    transition: "none",
                  }}
                />
              )}
            </div>
          </div>
        </div>
      </AbsoluteFill>

      {/* FILM GRAIN / TEXTURE OVERLAY (RENDERED ON TOP) */}
      <svg width="100%" height="100%" style={{ position: "absolute", pointerEvents: "none", zIndex: 20, opacity: 0.04, mixBlendMode: "overlay" }}>
        <defs>
          <filter id={grainId}>
            <feTurbulence type="fractalNoise" baseFrequency="0.65" numOctaves="3" stitchTiles="stitch" />
          </filter>
        </defs>
        <rect width="100%" height="100%" filter={`url(#${grainId})`} />
      </svg>

    </AbsoluteFill>
  );
};

export default MacromoneyTitle;